sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float radius;
uniform float mode;
uniform float softness;
uniform float amount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 best = c;
    float amax = c.a;
    float amin = c.a;
    for (int k = 0; k < 3; k++) {
        float rr = radius * (float(k) + 1.0) / 3.0;
        for (int i = 0; i < 12; i++) {
            float a = float(i) * 0.5235988;
            float4 s4 = tex(coord + float2(cos(a), sin(a)) * rr);
            if (s4.a > best.a) best = s4;
            amax = max(amax, s4.a);
            amin = min(amin, s4.a);
        }
    }
    float na = mode < 0.5 ? amin : amax;
    na = mix(na, mix(c.a, na, 0.5), softness);
    na = mix(c.a, na, amount);
    float3 col = mode < 0.5 ? unp(c) : unp(best);
    return fin(c, float4(col * na, na), opacity);
}
